class ControllerProgramVoicesRuntime final {
 using T=ProgramVoicesTask;using S=T::Stage;using V=VoiceAddressTask;using K=ProgramHeldKeysClearTask;
public:
 enum class Block:uint8_t{None,NotBound,Inactive,NeedsInterrupt,UnsupportedMode,DspBusy};struct Result{unsigned clocks=0;bool returned=false;Block blocked=Block::None;};
 bool bindVerifiedFirmware(ControllerDeviceState&d,const uint8_t*image,size_t size){if(bound_||active()||!image||size!=49728||!d.hasImmutableCapacity(10))return false;for(auto r:ranges_)for(auto a=r.begin;a<r.end;++a)if(d.readResource(a)!=image[a]||d.readResource(0x400000+a)!=image[a])return false;for(auto r:ranges_)if(!d.protectImmutableVerified(r.begin,r.end,image+r.begin)||!d.protectImmutableVerified(0x400000+r.begin,0x400000+r.end,image+r.begin))return false;bound_=&d;return true;}
 bool boundTo(const ControllerDeviceState&d)const{return bound_==&d;}bool active()const{return bool(task_);}bool start(uint8_t part,bool release=false){if(!bound_||active())return false;task_.emplace(part,release);return true;}void reset(){task_.reset();voice_.reset();select_.reset();word_.reset();keys_.reset();ownsDsp_=false;}
 unsigned nextClocks(const ControllerDeviceState&d,const ControllerInterruptRuntime&irq,const ControllerDspTransferRuntime&dsp)const{if(bound_!=&d||!irq.boundTo(d)||!dsp.boundTo(d)||!active()||d.interruptMode2||d.pendingIrqsHigh||irq.active()||(d.pendingIrqs&&irq.mask()==ControllerInterruptRuntime::Mask::Enabled)||(dsp.active()&&!ownsDsp_))return 0;if(ownsDsp_)return dsp.nextClocks(d,irq);auto c=word_?word_->nextClocks():select_?select_->nextClocks():voice_?voice_->nextClocks({3,7}):keys_?keys_->nextClocks(keyCredits(d.lastWrite)):task_->nextClocks(credits(d.lastWrite));return c?c+(d.pendingIrqs?1u:0u):0;}
 Result advanceBefore(ControllerDeviceState&d,ControllerInterruptRuntime&irq,ControllerDspTransferRuntime&dsp,unsigned budget){if(bound_!=&d||!irq.boundTo(d)||!dsp.boundTo(d))return {0,false,Block::NotBound};if(!active())return {0,false,Block::Inactive};if(d.interruptMode2||d.pendingIrqsHigh)return {0,false,Block::UnsupportedMode};if(irq.active()||(d.pendingIrqs&&irq.mask()==ControllerInterruptRuntime::Mask::Enabled))return {0,false,Block::NeedsInterrupt};if(dsp.active()&&!ownsDsp_)return {0,false,Block::DspBusy};if(ownsDsp_){auto r=dsp.advanceBefore(d,irq,budget);if(r.returned){ownsDsp_=false;if(word_)word_->resumeDsp();else select_->resumeDsp();}return {r.clocks,false,Block::None};}auto c=word_?word_->nextClocks():select_?select_->nextClocks():voice_?voice_->nextClocks({3,7}):keys_?keys_->nextClocks(keyCredits(d.lastWrite)):task_->nextClocks(credits(d.lastWrite)),arb=d.pendingIrqs?1u:0u;if(!c||budget<c+arb)return {};if(arb)(void)d.read8(0xfffff2);auto begin=d.cycles;auto history=[](uint32_t a){a&=0xffffff;return a<0x400000||(a>=0xfffd10&&a<0xffffa0)?int(a):-1;};auto read=[&](uint32_t a,unsigned n,unsigned end){uint32_t v=0;unsigned total=n==4?((a<0x400000)?6:2):((a<0x400000)?3:1),first=n==4?total/2:total;for(unsigned i=0;i<n;++i){d.cycles=begin+end-total+(i<2?first:total);d.lastRead=history(a+i);v=(v<<8)|d.readResource(a+i);}return v;};auto write=[&](uint32_t a,uint32_t v,unsigned n,unsigned end){unsigned total=n==4?((a<0x400000)?6:2):((a<0x400000)?3:1),first=n==4?total/2:total;for(unsigned i=0;i<n;++i){d.cycles=begin+end-total+(i<2?first:total);d.lastWrite=history(a+i);d.writeResource(a+i,uint8_t(v>>(8*(n-i-1))));}};bool stack=false;
 if(voice_){voice_->advanceBefore(c,{3,7},[&](){return read(0xd023,1,c);});if(voice_->complete()){auto v=voice_->address();voice_.reset();task_->resumeChild(v);}}
 else if(word_){stack=word_->stackWrites();word_->advanceBefore(c,read);if(word_->awaitingDsp()){if(!dsp.startWrite(word_->address(),word_->word()))return {};ownsDsp_=true;}else if(word_->complete()){word_.reset();task_->resumeChild();}}
 else if(select_){stack=select_->stackWrites();select_->advanceBefore(c,read,write);if(select_->awaitingDsp()){bool ok=select_->isWrite()?dsp.startWrite(select_->address(),0):dsp.startInvalidate();if(!ok)return {};ownsDsp_=true;}else if(select_->complete()){select_.reset();task_->resumeChild();}}
 else if(keys_){auto st=keys_->stage();stack=st==K::Stage::RetainValue||st==K::Stage::RetainPointer;keys_->advanceBefore(c,keyCredits(d.lastWrite),[&](unsigned i,unsigned v){write(0xcbed-i,v,1,c-2);});if(keys_->complete()){keys_.reset();task_->resumeChild();}}
 else{auto st=task_->stage();stack=st==S::RetainCount||st==S::RetainPart||st==S::RetainMode||st==S::RetainModeValue||st==S::SelectVoice||st==S::SelectDsp||st==S::WriteGain||st==S::WriteGate||st==S::ClearKeys;auto cr=credits(d.lastWrite);task_->advanceBefore(c,cr,[&](T::Read f){uint32_t a=f==T::Read::Part?0xd028:f==T::Read::Count?0xd022:f==T::Read::Age?task_->voice()+8:f==T::Read::Owner?task_->voice()+4:f==T::Read::Patch?task_->voice():0xd023;return read(a,f==T::Read::Patch?4:f==T::Read::Age?2:1,c);},[&](T::Write f,uint32_t v){write(f==T::Write::Part?0xd028:f==T::Write::Age?task_->voice()+8:0xd023,v,f==T::Write::Age?4:1,c);});if(task_->awaiting()){switch(task_->child()){case T::Child::Voice:voice_.emplace();break;case T::Child::Dsp:select_.emplace(ControllerVoiceReleaseDspTask::Kind::Select);break;case T::Child::Gain:word_.emplace(0x55,0x100000);break;case T::Child::Gate:select_.emplace(ControllerVoiceReleaseDspTask::Kind::Gate);break;case T::Child::Keys:keys_.emplace();break;default:break;}}}
 d.cycles=begin+c;d.lastRead=-1;if(stack)d.lastWrite=-1;bool done=task_->complete();if(done)task_.reset();return {c+arb,done,Block::None};}
private:
 struct Range{uint32_t begin,end;};inline static constexpr Range ranges_[]={{0x763e,0x76d6},{0x2baa,0x2bc8},{0x72ba,0x72ce},{0x5bb8,0x5c04},{0x6f44,0x6f50}};
 static unsigned bus(uint32_t a,unsigned n,int p){unsigned c=0;for(unsigned i=0;i<n;++i){auto x=(a+i)&0xffffff;if(x<0x400000||(x>=0xfffd10&&x<0xffffa0)){if((p&1)||x!=uint32_t(p|1))c+=x<0x400000?3:1;p=int(x);}else{c+=x>=0xffffa0?1:3;p=-1;}}return c;}
 FlashCredits credits(int last)const{FlashCredits c{};auto s=task_->stage();uint32_t a=0;unsigned n=0;bool wr=false;switch(s){case S::PublishPart:a=0xd028;n=1;wr=true;break;case S::PublishIndex:case S::WriteIndex:a=0xd023;n=1;wr=true;break;case S::ReadPart:a=0xd028;n=1;break;case S::ReadCount:a=0xd022;n=1;break;case S::ReadAge:a=task_->voice()+8;n=2;break;case S::ReadOwner:a=task_->voice()+4;n=1;break;case S::ReadPatch:a=task_->voice();n=4;break;case S::PublishAge:a=task_->voice()+8;n=4;wr=true;break;case S::ReadIndex:a=0xd023;n=1;break;default:break;}if(n)(wr?c.write:c.read)=bus(a,n,wr?last:-1);return c;}
 FlashCredits keyCredits(int last)const{FlashCredits c{};if(keys_&&keys_->stage()==K::Stage::Publish)c.write=bus(0xcbed-keys_->index(),1,last);return c;}
 ControllerDeviceState*bound_=nullptr;std::optional<T>task_{};std::optional<V>voice_{};std::optional<K>keys_{};std::optional<ControllerVoiceReleaseDspTask>select_{};std::optional<ControllerVoiceDspWordTask>word_{};bool ownsDsp_=false;
};
